import 'firebase_options.dart';

/// App-level configuration that is not generated by `flutterfire configure`.
class AppConfig {
  AppConfig._();

  static const String appName = 'Habitual Offender';

  /// Optional. The *Web* OAuth client ID from Firebase → Authentication →
  /// Sign-in method → Google ("Web SDK configuration").
  ///
  /// Leave the placeholder and Google Sign-In reads the ID from
  /// android/app/google-services.json instead, as long as that file was
  /// downloaded *after* enabling the Google provider.
  static const String googleServerClientId =
      'YOUR_WEB_CLIENT_ID.apps.googleusercontent.com';

  /// True once firebase_options.dart holds real values.
  static bool get firebaseConfigured =>
      !DefaultFirebaseOptions.currentPlatform.apiKey.startsWith('YOUR_');

  static bool get googleConfigured =>
      !googleServerClientId.startsWith('YOUR_');
}
